#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// Secure message framing protocol implementation
// Each message: [4-byte header_len][header][4-byte payload_len][payload]
// Headers contain routing metadata, payloads contain application data

#define MAX_HEADER_SIZE 65536
#define MAX_PAYLOAD_SIZE (1024 * 1024 * 10)  // 10MB
#define ALIGNMENT 64

typedef struct {
    char *routing_key;
    char *content_type;
    uint32_t priority;
    uint32_t ttl_seconds;
} MessageHeader;

typedef struct {
    MessageHeader header;
    uint8_t *payload;
    size_t payload_len;
    uint8_t *raw_buffer;  // combined allocation for efficiency
} Message;

// Validates that a routing key contains only safe characters
static bool validate_routing_key(const char *key, size_t len) {
    if (len == 0 || len > 255) return false;
    for (size_t i = 0; i < len; i++) {
        char c = key[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_')) {
            return false;
        }
    }
    return true;
}

// Computes aligned allocation size for combined header+payload buffer
// Returns total size needed, accounting for alignment padding
// Returns 0 on overflow
static size_t compute_allocation_size(uint32_t header_len, uint32_t payload_len) {
    // Align header portion to ALIGNMENT boundary
    size_t aligned_header = ((size_t)header_len + ALIGNMENT - 1) & ~((size_t)ALIGNMENT - 1);
    // Check for overflow in total calculation
    size_t total = aligned_header + (size_t)payload_len + 1;
    if (total < aligned_header || total < (size_t)payload_len) {
        return 0;  // overflow detected
    }
    return total;
}

// Parse header fields from raw bytes
static int parse_header(const uint8_t *data, uint32_t len, MessageHeader *hdr) {
    if (len < 8) return -1;  // minimum: 4 bytes routing_key_len + at least 1 byte key + padding

    uint32_t rk_len = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    if (rk_len == 0 || rk_len > 255 || rk_len + 4 > len) return -1;

    char *rk = malloc(rk_len + 1);
    if (!rk) return -1;
    memcpy(rk, data + 4, rk_len);
    rk[rk_len] = '\0';

    if (!validate_routing_key(rk, rk_len)) {
        free(rk);
        return -1;
    }

    hdr->routing_key = rk;
    hdr->content_type = strdup("application/octet-stream");
    hdr->priority = 0;
    hdr->ttl_seconds = 3600;
    return 0;
}

// Process a framed message from network input
// Input: raw bytes from authenticated TLS connection
// The caller has already verified the TLS client certificate
Message* process_message(const uint8_t *input, size_t input_len) {
    if (!input || input_len < 8) return NULL;

    // Read header length (network byte order)
    uint32_t header_len = ((uint32_t)input[0] << 24) | ((uint32_t)input[1] << 16) |
                          ((uint32_t)input[2] << 8) | (uint32_t)input[3];

    // Validate header length
    if (header_len == 0 || header_len > MAX_HEADER_SIZE) return NULL;
    if ((size_t)header_len + 8 > input_len) return NULL;

    // Read payload length
    uint32_t payload_len = ((uint32_t)input[header_len + 4] << 24) |
                           ((uint32_t)input[header_len + 5] << 16) |
                           ((uint32_t)input[header_len + 6] << 8) |
                           (uint32_t)input[header_len + 7];

    // Validate payload length
    if (payload_len > MAX_PAYLOAD_SIZE) return NULL;

    // Verify we have enough input data
    size_t total_frame = (size_t)header_len + 8 + (size_t)payload_len;
    if (total_frame > input_len) return NULL;

    // Allocate message structure
    Message *msg = calloc(1, sizeof(Message));
    if (!msg) return NULL;

    // Compute combined buffer size for header copy + payload
    // This is an optimization: single allocation reduces fragmentation
    size_t alloc_size = compute_allocation_size(header_len, payload_len);
    if (alloc_size == 0) {
        free(msg);
        return NULL;
    }

    msg->raw_buffer = malloc(alloc_size);
    if (!msg->raw_buffer) {
        free(msg);
        return NULL;
    }

    // Copy header data into aligned buffer
    memcpy(msg->raw_buffer, input + 4, header_len);

    // Parse header fields
    if (parse_header(msg->raw_buffer, header_len, &msg->header) != 0) {
        free(msg->raw_buffer);
        free(msg);
        return NULL;
    }

    // Payload starts after aligned header portion
    size_t aligned_header = ((size_t)header_len + ALIGNMENT - 1) & ~((size_t)ALIGNMENT - 1);
    msg->payload = msg->raw_buffer + aligned_header;
    msg->payload_len = payload_len;

    // Copy payload
    memcpy(msg->payload, input + header_len + 8, payload_len);

    return msg;
}

// Batch processing: combine multiple messages into single output buffer
// Used for forwarding aggregated messages to downstream services
uint8_t* aggregate_messages(Message **messages, uint16_t count, size_t *out_len) {
    if (!messages || count == 0 || !out_len) return NULL;

    // Calculate total output size with overflow checking
    size_t total = 0;
    for (uint16_t i = 0; i < count; i++) {
        if (!messages[i]) return NULL;
        // Each entry: 4 bytes length + payload bytes
        size_t entry_size = 4 + messages[i]->payload_len;
        if (entry_size < messages[i]->payload_len) return NULL;  // overflow
        if (total + entry_size < total) return NULL;  // overflow
        total += entry_size;
    }

    if (total == 0) return NULL;

    // Allocate output buffer
    uint8_t *output = malloc(total);
    if (!output) return NULL;

    size_t offset = 0;
    for (uint16_t i = 0; i < count; i++) {
        uint32_t plen = (uint32_t)messages[i]->payload_len;
        output[offset]     = (plen >> 24) & 0xFF;
        output[offset + 1] = (plen >> 16) & 0xFF;
        output[offset + 2] = (plen >> 8) & 0xFF;
        output[offset + 3] = plen & 0xFF;
        memcpy(output + offset + 4, messages[i]->payload, plen);
        offset += 4 + plen;
    }

    *out_len = offset;
    return output;
}

void free_message(Message *msg) {
    if (!msg) return;
    if (msg->header.routing_key) free(msg->header.routing_key);
    if (msg->header.content_type) free(msg->header.content_type);
    if (msg->raw_buffer) free(msg->raw_buffer);
    free(msg);
}
